// Lê o HTML da página de ofertas e devolve um item por produto, já no formato
// que POST /api/v1/products espera: { name, description, externalLink, imageUrl }.
const html = $input.first().json.data;

if (typeof html !== 'string' || html.length === 0) {
  throw new Error('A página de ofertas veio vazia.');
}

const AMAZON = 'https://www.amazon.com.br';
const NAME_MAX = 200; // limite do campo name na API
const DESCRIPTION_MAX = 2000; // limite do campo description na API

const decodeEntities = (text) =>
  text
    .replace(/&#x([0-9a-f]+);/gi, (_, hex) => String.fromCodePoint(parseInt(hex, 16)))
    .replace(/&#(\d+);/g, (_, dec) => String.fromCodePoint(Number(dec)))
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&');

const clean = (text) => decodeEntities(text).replace(/\s+/g, ' ').trim();

const truncate = (text, max) => (text.length <= max ? text : `${text.slice(0, max - 1).trimEnd()}…`);

const formatBRL = (value) => {
  const number = Number(value);
  if (!Number.isFinite(number)) return null;
  const [whole, cents] = number.toFixed(2).split('.');
  return `R$ ${whole.replace(/\B(?=(\d{3})+(?!\d))/g, '.')},${cents}`;
};

// O link canônico (só o ASIN) não muda entre execuções, então serve de chave
// para não cadastrar o mesmo produto duas vezes.
const productLink = (asin) => `${AMAZON}/dp/${asin}`;

const products = new Map();

const add = ({ asin, name, description, imageUrl }) => {
  if (!asin || !name || !imageUrl || !imageUrl.startsWith('https://')) return;
  if (products.has(asin)) return;
  products.set(asin, {
    asin,
    name: truncate(name, NAME_MAX),
    description: description ? truncate(description, DESCRIPTION_MAX) : undefined,
    externalLink: productLink(asin),
    imageUrl,
  });
};

// Extrai o objeto JSON que começa logo depois de `marker`, contando chaves e
// respeitando strings (o JSON fica embutido no meio de um <script>).
const extractObjectAfter = (source, marker) => {
  const markerIndex = source.indexOf(marker);
  if (markerIndex === -1) return null;
  const start = source.indexOf('{', markerIndex + marker.length);
  if (start === -1) return null;

  let depth = 0;
  let inString = false;
  let escaped = false;
  for (let i = start; i < source.length; i++) {
    const char = source[i];
    if (inString) {
      if (escaped) escaped = false;
      else if (char === '\\') escaped = true;
      else if (char === '"') inString = false;
    } else if (char === '"') inString = true;
    else if (char === '{') depth++;
    else if (char === '}') {
      depth--;
      if (depth === 0) {
        try {
          return JSON.parse(source.slice(start, i + 1));
        } catch {
          return null;
        }
      }
    }
  }
  return null;
};

// 1) Grade principal de ofertas: vem como JSON embutido na página.
const grid = extractObjectAfter(html, '"productSearchResponse":');
for (const product of grid?.products ?? []) {
  const image = product.image?.hiRes ?? product.image?.lowRes;
  const parts = [];

  const price = formatBRL(product.price?.priceToPay?.price);
  const oldPrice = formatBRL(product.price?.basisPrice?.price);
  if (price) parts.push(oldPrice ? `Oferta: ${price} (de ${oldPrice})` : `Oferta: ${price}`);

  const discount = product.dealBadge?.label?.content?.fragments?.map((fragment) => fragment.text ?? '').join('').trim();
  if (discount) parts.push(discount);

  const rating = product.customerReviews?.rating?.shortDisplayString;
  const reviewCount = product.customerReviews?.count?.displayString;
  if (rating) parts.push(`Nota ${rating} de 5 na Amazon${reviewCount ? ` (${reviewCount} avaliações)` : ''}`);

  add({
    asin: product.asin,
    name: clean(product.title ?? ''),
    description: parts.join(' · '),
    imageUrl: image?.baseUrl ? `${image.baseUrl}.${image.extension ?? 'jpg'}` : null,
  });
}

// 2) Carrosséis da página: vêm como HTML.
const firstMatch = (source, pattern) => source.match(pattern)?.[1] ?? null;

for (const rawCard of html.split('class="dcl-product-wrapper"').slice(1)) {
  const end = rawCard.indexOf('</li>');
  const card = (end === -1 ? rawCard : rawCard.slice(0, end)).replace(/<style[\s\S]*?<\/style>/g, '');

  const asin = firstMatch(card, /data-csa-c-item-id="amzn1\.asin\.([A-Z0-9]{10})"/);
  const title = firstMatch(card, /dcl-product-title"[^>]*><span>([\s\S]*?)<\/span>/);
  const imageId = firstMatch(card, /<img[^>]*src="https:\/\/m\.media-amazon\.com\/images\/I\/([^."]+)\./);
  if (!asin || !title || !imageId) continue;

  const parts = [];
  const price = firstMatch(card, /dcl-product-price-new[\s\S]*?a-offscreen">([^<]+)</);
  const oldPrice = firstMatch(card, /dcl-product-price-old[\s\S]*?a-offscreen">([^<]+)</);
  if (price) parts.push(oldPrice ? `Oferta: ${clean(price)} (de ${clean(oldPrice)})` : `Oferta: ${clean(price)}`);

  const rating = firstMatch(card, /dcl-product-rating-value">([^<]+)</);
  const reviewCount = firstMatch(card, /dcl-product-rating-count">([^<]+)</);
  if (rating) parts.push(`Nota ${clean(rating)} de 5 na Amazon${reviewCount ? ` (${clean(reviewCount)} avaliações)` : ''}`);

  add({
    asin,
    name: clean(title),
    description: parts.join(' · '),
    imageUrl: `https://m.media-amazon.com/images/I/${imageId}._AC_SL600_.jpg`,
  });
}

if (products.size === 0) {
  throw new Error(
    'Nenhum produto encontrado no HTML. A Amazon pode ter devolvido um captcha ou mudado a estrutura da página.',
  );
}

return [...products.values()].map((json) => ({ json }));

// Compara os produtos mapeados com os que a API já tem, pelo link do produto,
// para que rodar o workflow de novo não crie duplicatas.
const existentes = new Set();
for (const pagina of $('Listar produtos existentes').all()) {
  for (const produto of pagina.json.items ?? []) {
    existentes.add(produto.externalLink);
  }
}

return $('Mapear produtos')
  .all()
  .filter((item) => !existentes.has(item.json.externalLink))
  .map((item) => ({ json: item.json }));

// Resume a execução: quantos produtos a página tinha, quantos eram novos
// e quantos a API aceitou.
const novos = $('Filtrar produtos novos').all().length;
const falhas = $input.all().filter((item) => item.json.error);

return [
  {
    json: {
      mapeados: $('Mapear produtos').all().length,
      novos,
      cadastrados: novos - falhas.length,
      falhas: falhas.length,
      erros: falhas
        .slice(0, 10)
        .map((item) => item.json.error?.message ?? String(item.json.error)),
    },
  },
];
